        {"role_title":"mechanical engineer","relevance":"conditional vehicle dynamics/control design","condition":"Relevant when work covers vehicle-motion models, control-system design/deployment or motion validation; not a general mechanical-engineering requirement.","role_source_ids":["D166-LUCID-PLANNING-CONTROL-ENGINEER-2026-10-23"]},
        {"role_title":"powertrain engineer","relevance":"conditional propulsion response and vehicle-control integration","condition":"Relevant when propulsion/actuation dynamics constrain vehicle-motion requests; it does not make MPC or RL a default powertrain skill.","role_source_ids":["D166-ROLE-POWERTRAIN-CONTROLS-2026-10-22"]}
