    _risk_tech_established["evidence_ids"] = list(dict.fromkeys(_risk_tech_established.get("evidence_ids", []) + ["D011-LE-MIDAS-VAR-ES-COMPARISON-2020","D011-CALMON-ESTABLISHED-VAR-COMPARISON-2021"]))
