    _risk_methods_current = area_matrix_claim_mappings[("D011:quantitative-financial-risk-modeling", "methods_and_designs", "current")]
    _risk_methods_current["claim_mappings"].append({
        "claim": "Current backtesting separates two questions: VaR hit tests evaluate exceedance frequency and temporal independence, while ES tests assess tail-loss severity or cumulative tail violations and may require the forecast tail distribution. Method families include Kupiec unconditional coverage, Christoffersen conditional coverage/independence, McNeil-Frey exceedance-residual testing, Acerbi-Szekely conditional/unconditional/quantile or minimally biased tests, and Du-Escanciano cumulative-violation tests.",
        "locator": "CRAN rugarch VaRTest/ESTest reference manual; Acerbi-Szekely (2014) author paper; Du and Escanciano, Management Science (2017) publisher abstract; MathWorks R2026b ES backtesting overview; Basel MAR32/MAR33.",
        "source_ids": ["D011-RUGARCH-CRAN-REFERENCE-AND-TESTS-2026", "D011-ACERBI-SZEKELY-ES-BACKTESTS-2014", "D011-DU-ESCANCIANO-ES-BACKTEST-2017", "D011-MATHWORKS-ES-BACKTEST-TEST-FAMILIES-2026", "D011-BIS-MAR32-BACKTESTING-PLA-CURRENT", "D011-BIS-MAR33-EXPECTED-SHORTFALL-2026"],
        "area_context": "These tests apply after risk-forecast generation and address distinct validation targets. Regulatory VaR backtesting and P&L attribution under Basel MAR32 do not make ES backtesting identical to VaR testing; ES capital under MAR33 is a separate risk-measure calculation.",
        "claim_limit": "ES tests can be sensitive to VaR forecast error and may depend on full conditional-tail information, finite-sample critical values or distributional assumptions. The source set includes a publisher abstract for Du-Escanciano and vendor implementation guidance; verify full formulas and test power before making method rankings. Applicability of Basel requirements depends on local transposition and model scope.",
        "relationship_context": "A conditional risk forecast first produces VaR and ES; VaR hit indicators support frequency/independence tests; ES evaluation also uses tail-loss magnitude or tail-distribution information. A VaR test should not be presented as sufficient ES validation. Method comparison should use the same portfolio P&L, horizon, confidence level, forecast window and data availability."
    })
    _risk_methods_current["search_log_ids"] = list(dict.fromkeys(_risk_methods_current.get("search_log_ids", []) + ["D011-QRISK-VOLATILITY-AND-VAR-ES-BACKTEST-TOOLS-20261024"]))

