            _portfolio_multiplicity_sources = ["D011-HSU-HAN-WU-CAO-PORTFOLIO-DATA-SNOOPING-2018", "D011-DICHTL-DROBETZ-WENDT-FACTOR-ALLOCATION-SPA-2021", "D011-HARVEY-LIU-ZHU-FACTOR-MULTIPLE-TESTING-2016", "D011-WHITE-REALITY-CHECK-2000", "D011-HANSEN-SPA-2005", "D011-ROMANO-WOLF-STEPM-2005", "D011-HANSEN-LUNDE-NASON-MCS-2011", "D011-BAILEY-LOPEZ-DSR-2014", "D011-PBO-BACKTEST-OVERFIT-2017", "D011-ARCH-MCP-IMPLEMENTATION-CODE-7-2-2026", "D011-CRAN-MCS-IMPLEMENTATION-0-2-1-2026", "D011-GOYAL-WELCH-ZAFIROV-EQUITY-PREMIUM-2022-LOOK-2024", "D011-OLAGOKE-LLM-TRIAL-ADJUSTED-OUTSAMPLE-GATE-2026"]
